mapper.select:
select * from payment_event
where order_number = #{orderNumber}
order by created_at desc, id desc

select * from payment_event


        and order_number = #{orderNumber}


        and provider = #{provider}


        and event_type = #{eventType}


        and result = #{result}


        and provider_trade_no = #{providerTradeNo}


        and idempotency_key = #{idempotencyKey}


        and created_at >= #{beginTime}


        and created_at <= #{endTime}


order by created_at desc, id desc

select request_event.*
from payment_event request_event

    request_event.event_type = 'REQUEST_CREATED'
    and request_event.result = 'PENDING'
    and not exists (
        select 1
        from payment_event terminal_event
        where terminal_event.order_number = request_event.order_number
          and terminal_event.provider = request_event.provider
          and terminal_event.event_type in ('CALLBACK_SUCCEEDED', 'CALLBACK_REJECTED')
    )

        and request_event.order_number = #{orderNumber}


        and request_event.provider = #{provider}


        and request_event.created_at >= #{beginTime}


        and request_event.created_at <= #{endTime}


order by request_event.created_at desc, request_event.id desc
